def make_wb(name, sheet_xml, ss_xml, wb_xml):
    d = 'D:/temp/xlsx_build/' + name
    if os.path.exists(d):
        shutil.rmtree(d)
    os.makedirs(d)
    os.makedirs(d + '/xl/worksheets')
    os.makedirs(d + '/xl/_rels')
    os.makedirs(d + '/_rels')
    with open(d+'/xl/styles.xml','w',encoding='utf-8') as f: f.write(STYLES)
    with open(d+'/xl/sharedStrings.xml','w',encoding='utf-8') as f: f.write(ss_xml)
    with open(d+'/xl/worksheets/sheet1.xml','w',encoding='utf-8') as f: f.write(sheet_xml)
    with open(d+'/xl/workbook.xml','w',encoding='utf-8') as f: f.write(wb_xml)
    with open(d+'/xl/_rels/workbook.xml.rels','w',encoding='utf-8') as f: f.write(WBREL)
    with open(d+'/_rels/.rels','w',encoding='utf-8') as f: f.write(RELS)
    with open(d+'/[Content_Types].xml','w',encoding='utf-8') as f: f.write(CT)
    zip_path = d + '.xlsx'
    if os.path.exists(zip_path):
        os.remove(zip_path)
    with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        zf.writestr('[Content_Types].xml', open(d+'/[Content_Types].xml','rb').read())
        zf.writestr('_rels/.rels', open(d+'/_rels/.rels','rb').read())
        zf.writestr('xl/workbook.xml', open(d+'/xl/workbook.xml','rb').read())
        zf.writestr('xl/_rels/workbook.xml.rels', open(d+'/xl/_rels/workbook.xml.rels','rb').read())
        zf.writestr('xl/styles.xml', open(d+'/xl/styles.xml','rb').read())
        zf.writestr('xl/sharedStrings.xml', open(d+'/xl/sharedStrings.xml','rb').read())
        zf.writestr('xl/worksheets/sheet1.xml', open(d+'/xl/worksheets/sheet1.xml','rb').read())
    shutil.copy(zip_path, OUTPUT_DIR+'/'+name+'.xlsx')
    print(f'Created: {name}.xlsx')

